import { IBaseClub } from '@apps/Clubs/@types/clubs.types';
import PohInput, { IPohInputProps } from '@ui-kit/Input';

import { selectClubAsync } from '../ClubSelectModal';

interface IClubSelectProps extends Omit<IPohInputProps, 'value' | 'onChange'> {
  value: Pick<IBaseClub, 'id' | 'name'> | null;
  onChange?: (v: IBaseClub) => void;
}

const ClubSelectInput = ({ value, onChange, ...props }: IClubSelectProps) => {
  return (
    <PohInput
      readOnly
      placeholder="Выберите клуб"
      name="id_club"
      className="w-100 flex-grow-1"
      {...props}
      value={value?.name || ''}
      onClick={() => {
        selectClubAsync({ filter: { my: true } }).then((club) => {
          onChange?.(club);
        });
      }}
    />
  );
};

export default ClubSelectInput;
