import { IGeoRegion } from '@apps/Routes/@services/geo.services';
import PohInput, { IPohInputProps } from '@ui-kit/Input';

import { selectGeoRegionOneAsync } from '.';

interface IGeoRegionSelectInputProps extends Omit<IPohInputProps, 'value' | 'onChange'> {
  value: Pick<IGeoRegion, 'id' | 'name'> | null;
  onChange?: (v: IGeoRegion) => void;
}

const GeoRegionSelectInput = ({ value, onChange, ...props }: IGeoRegionSelectInputProps) => {
  return (
    <PohInput
      readOnly
      placeholder="Выберите регион"
      name="id_club"
      className="w-100 flex-grow-1"
      {...props}
      value={value?.name || ''}
      onClick={() => {
        selectGeoRegionOneAsync({}).then((g) => {
          g && onChange?.(g);
        });
      }}
    />
  );
};

export default GeoRegionSelectInput;
