import { IGetClubsCriteria } from '@apps/Clubs/@types/clubs.dto.types';
import { IClub } from '@apps/Clubs/@types/clubs.types';
import { showModal } from '@ui-kit/Modal';

import ClubsList from '../ClubsList';

interface IClubSelectModalProps {
  filter?: IGetClubsCriteria;
  onSelect: (ro: IClub) => void;
}

const ClubSelectModal = ({ filter, onSelect }: IClubSelectModalProps) => {
  return (
    <div style={{ overflowY: 'auto', minWidth: 400, maxHeight: 300 }}>
      <ClubsList
        criteria={filter}
        withSearch
        listItemPatcher={(x) => ({
          onClick: (e) => {
            e.preventDefault();
            onSelect(x);
          },
        })}
      />
    </div>
  );
};

export function selectClubAsync({
  filter,
  title = 'Выбор клуба',
}: {
  filter: IGetClubsCriteria;
  title?: string;
}): Promise<IClub> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: title,
      children: (closeHandler: () => void) => (
        <ClubSelectModal
          filter={filter}
          onSelect={(s) => {
            resolve(s);
            closeHandler();
          }}
        />
      ),
    });
  });
}
